    marker = next(c for c, n in counts.most_common() if c != bg and n > 1)
    seed = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
            if grid[r][c] not in (bg, marker)]

    # Read the seed as a straight run; its orientation determines the
    # ordered motif, which is then laid horizontally at each marker.
    rs = sorted(set(r for r, c, v in seed))
    cs = sorted(set(c for r, c, v in seed))
    if len(cs) == 1:
        motif = [grid[r][cs[0]] for r in rs]
    elif len(rs) == 1:
        motif = [grid[rs[0]][c] for c in cs]
    else:
        # Fallback: order seed cells along their dominant axis.
        if max(rs) - min(rs) >= max(cs) - min(cs):
            motif = [v for r, c, v in sorted(seed)]
        else:
            motif = [v for r, c, v in sorted(seed, key=lambda x: x[1])]

    out = [row[:] for row in grid]
    mid = len(motif) // 2
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker:
                start = c - mid
                for i, value in enumerate(motif):
                    if 0 <= start + i < w:
                        out[r][start + i] = value
    return out
