def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    marker = next(v for v, n in counts.most_common() if v != bg and n > 1)

    seeds = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] not in (bg, marker)]
    rows = [r for r, c, v in seeds]
    cols = [c for r, c, v in seeds]
    vertical = max(rows) - min(rows) > max(cols) - min(cols)

    if vertical:
        motif = [grid[r][cols[0]] for r in range(min(rows), max(rows) + 1)]
    else:
        motif = [grid[rows[0]][c] for c in range(min(cols), max(cols) + 1)]

    out = [row[:] for row in grid]
    mid = len(motif) // 2
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker:
                for i, value in enumerate(motif):
                    if vertical:
                        rr, cc = r + i - mid, c
                    else:
                        rr, cc = r, c + i - mid
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = value
    return out
